    if not os.path.exists(p): return f"<p><i>[missing figure {name}]</i></p>"
    return f'<figure style="width:{w if w != "100%" else "100%"}"><img src="data:image/png;base64,{base64.b64encode(open(p, "rb").read()).decode()}"><figcaption><b>Fig. {FIGN[0]}.</b> {cap}</figcaption></figure>'
