def over(r):
    gap_ll = r["cv_logloss"] - r["fold_train_logloss"]; gap_f1 = r["train_macro_f1"] - r["cv_macro_f1"]
    if r["cv_logloss"] > 0.3: return f"Underfitting / mis-specification: both train and validation are poor (CV log loss {r['cv_logloss']:.3f}, train-fold log loss {r['fold_train_logloss']:.3f}); the Gaussian/independence assumption cannot fit the data."
    if gap_ll > 0.02 or gap_f1 > 0.03: return f"Mild-to-clear overfitting: train-fold log loss {r['fold_train_logloss']:.4f} vs CV {r['cv_logloss']:.4f} (gap {gap_ll:.4f}); train macro-F1 {r['train_macro_f1']:.4f} vs CV {r['cv_macro_f1']:.4f}."
    if r["cv_macro_f1"] < 0.9 and abs(gap_ll) < 0.02: return f"Mild underfitting: train and CV agree closely (train-fold log loss {r['fold_train_logloss']:.4f} vs CV {r['cv_logloss']:.4f}) but macro-F1 is limited (CV {r['cv_macro_f1']:.4f}), so capacity rather than variance is the bottleneck."
    return f"Well fit: train-fold log loss {r['fold_train_logloss']:.4f} vs CV {r['cv_logloss']:.4f} (gap {gap_ll:.4f}); train macro-F1 {r['train_macro_f1']:.4f} vs CV macro-F1 {r['cv_macro_f1']:.4f}."

